function updatePhaseReadout() { if (scene().kind !== 'phase') return; const measurement = phaseMeasurement(); $('sceneDescription').textContent = `${measurement.modelName} · ${measurement.arcName} · ${measurement.phase} · ${measurement.progress.toFixed(2)} · transition gap ${measurement.transitionGap.toFixed(3)}${measurement.compareReturnPath ? ' · return path right' : ''}`; const actionReadout = $('phaseActionReadout'); if (actionReadout) actionReadout.textContent = `Live current · ${measurement.arcName} · ${measurement.curve} · ${measurement.phase} ${measurement.progress.toFixed(2)} · ${measurement.tempo.toFixed(0)} BPM · control ${measurement.control.toFixed(2)} · gap ${measurement.transitionGap.toFixed(3)}`; const archiveReadout = $('phaseArchiveReadout'); if (archiveReadout) archiveReadout.textContent = phaseArchiveSummary(); }
function stepAndDraw(dt) { if (scene().kind === 'reaction') { stepAcid(dt); drawAcid(); } else if (scene().kind === 'automaton') { stepTapestry(dt); drawTapestry(); } else if (scene().kind === 'feedback') { stepFeedback(); drawFeedback(); } else if (scene().kind === 'particles') { stepMagnetic(dt); drawMagnetic(); } else if (scene().kind === 'geometry') { stepCathedrals(dt); drawCathedrals(); } else if (scene().kind === 'aquarium') { stepAquarium(dt); drawAquarium(); } else if (scene().kind === 'interference') { stepInterference(dt); drawInterference(); } else if (scene().kind === 'topology') { stepTopology(dt); drawTopology(); } else if (scene().kind === 'phase') { stepPhase(dt); drawPhase(); } else if (scene().kind === 'evolution') { stepEvolution(dt); drawEvolution(); } }
function renderFrame(now) { const dt = Math.min(.05, Math.max(0, (now - state.lastTime) / 1000)); state.lastTime = now; if (!state.paused && !state.blackout && !state.renderingLost) { state.elapsed += dt; updateAudioLevel(); state.cadenceAccumulator += dt; const cadence = 1 / outputProfile().cadence; if (state.cadenceAccumulator >= cadence || outputProfile().cadence === 60) { const renderDt = Math.min(.05, state.cadenceAccumulator); state.cadenceAccumulator = 0; stepAndDraw(renderDt); updatePhaseReadout(); metrics.sceneFrames[state.sceneIndex] += 1; } metrics.frameTimes.push(dt * 1000); metrics.sceneTimes[state.sceneIndex].push(dt * 1000); if (metrics.frameTimes.length > 3600) metrics.frameTimes.shift(); if (metrics.sceneTimes[state.sceneIndex].length > 360) metrics.sceneTimes[state.sceneIndex].shift(); } else if (state.blackout || state.renderingLost) { ctx.fillStyle = '#020207'; ctx.fillRect(0, 0, canvas.width, canvas.height); } if (state.transition) { state.transition.progress = Math.min(1, state.transition.progress + dt / 2.6); ctx.save(); ctx.globalAlpha = 1 - state.transition.progress; ctx.drawImage(transitionCanvas, 0, 0); ctx.restore(); if (state.transition.progress >= 1) state.transition = null; } if (!state.blackout && !state.renderingLost && state.brightness < 1) { ctx.save(); ctx.globalAlpha = 1 - state.brightness; ctx.fillStyle = '#000'; ctx.fillRect(0, 0, canvas.width, canvas.height); ctx.restore(); } $('fpsReadout').textContent = outputProfile().label; $('transitionBadge').textContent = state.renderingLost ? 'RECOVERING' : state.transition ? 'MORPHING' : state.setPlaying ? 'SET LIVE' : 'LIVE'; requestAnimationFrame(renderFrame); }

function updateAudioLevel() { if (!audio.analyser) { state.audioLevel += (0 - state.audioLevel) * .08; } else { audio.analyser.getByteTimeDomainData(audio.data); let sum = 0; for (const value of audio.data) { const n = (value - 128) / 128; sum += n * n; } const next = Math.sqrt(sum / audio.data.length); state.audioLevel += (next - state.audioLevel) * .08; } const mod = clamp(state.audioLevel * 4, 0, 1); $('modulationReadout').textContent = `AUDIO ${Math.round(mod * 100)}%`; if (!state.paused && !state.blackout && mod > .03) { if (scene().kind === 'reaction') state.params.acid.injection = clamp(state.params.acid.injection + (mod * .18 - state.params.acid.injection) * .003, 0, 1); if (scene().kind === 'feedback') state.params.feedback.decay = clamp(state.params.feedback.decay + (mod * .12 - .05) * .002, .72, .99); if (scene().kind === 'particles') state.params.magnetic.motion = clamp(state.params.magnetic.motion + (mod * .4 - state.params.magnetic.motion) * .003, .1, 1); if (scene().kind === 'interference') state.params.interference.phase = clamp(state.params.interference.phase + (mod * .2 - state.params.interference.phase) * .003, 0, 1); if (scene().kind === 'topology') state.params.topology.camera = clamp(state.params.topology.camera + (mod * .4 - state.params.topology.camera) * .003, 0, 1); if (scene().kind === 'phase') state.params.phase.control = clamp(state.params.phase.control + (mod * .4 - state.params.phase.control) * .003, 0, 1); } }
function stopAudioSource() { if (audio.source) { try { audio.source.stop?.(); } catch {} try { audio.source.disconnect(); } catch {} audio.source = null; } if (audio.demoGain) { try { audio.demoGain.disconnect(); } catch {} audio.demoGain = null; } if (audio.media) { audio.media.pause(); audio.media.removeAttribute('src'); audio.media.load(); audio.media = null; } if (audio.mediaUrl) { URL.revokeObjectURL(audio.mediaUrl); audio.mediaUrl = null; } if (audio.micStream) { audio.micStream.getTracks().forEach((track) => track.stop()); audio.micStream = null; } state.demoOn = false; }
async function ensureAudio() { if (audio.context) { await audio.context.resume(); return; } try { audio.context = new AudioContext(); audio.analyser = audio.context.createAnalyser(); audio.analyser.fftSize = 256; audio.data = new Uint8Array(audio.analyser.fftSize); audio.gain = audio.context.createGain(); audio.gain.gain.value = state.muted ? 0 : .18; audio.recordDestination = audio.context.createMediaStreamDestination(); audio.analyser.connect(audio.gain); audio.gain.connect(audio.context.destination); audio.gain.connect(audio.recordDestination); await audio.context.resume(); $('startAudioButton').textContent = '◉'; showToast('Audio engine ready · local only'); } catch { showToast('Audio could not start in this browser'); } }
async function toggleDemo() { await ensureAudio(); if (!audio.context) return; if (state.demoOn) { stopAudioSource(); $('demoAudioButton').textContent = 'Demo pulse'; showToast('Demo pulse stopped'); return; } stopAudioSource(); const osc = audio.context.createOscillator(); const gain = audio.context.createGain(); osc.type = 'sine'; osc.frequency.value = 110; gain.gain.value = .0001; osc.connect(gain); gain.connect(audio.analyser); osc.start(); const pulse = () => { if (!state.demoOn || !audio.context) return; const t = audio.context.currentTime; gain.gain.cancelScheduledValues(t); gain.gain.setValueAtTime(.0001, t); gain.gain.linearRampToValueAtTime(.12, t + .03); gain.gain.exponentialRampToValueAtTime(.0001, t + .42); setTimeout(pulse, Math.max(200, (60 / state.tempo) * 1000)); }; audio.source = osc; audio.demoGain = gain; state.demoOn = true; $('demoAudioButton').textContent = 'Stop pulse'; pulse(); showToast('Procedural demo pulse engaged'); }
async function loadLocalAudio(file) { if (!file) return; if (file.size > 80 * 1024 * 1024) return showToast('Audio is over the 80 MB local limit'); await ensureAudio(); if (!audio.context) return; stopAudioSource(); const url = URL.createObjectURL(file); const media = new Audio(url); media.loop = true; media.volume = .7; const source = audio.context.createMediaElementSource(media); source.connect(audio.analyser); audio.media = media; audio.mediaUrl = url; audio.source = source; try { await media.play(); showToast(`Local audio loaded · ${file.name}`); } catch { stopAudioSource(); showToast('Local audio playback was blocked · use Demo pulse or manual mode'); } }
async function toggleMic() { await ensureAudio(); if (!audio.context) return; if (audio.micStream) { stopAudioSource(); $('micButton').textContent = 'Mic: off'; return showToast('Microphone released'); } stopAudioSource(); try { audio.micStream = await navigator.mediaDevices.getUserMedia({ audio: true }); const source = audio.context.createMediaStreamSource(audio.micStream); source.connect(audio.analyser); audio.source = source; $('micButton').textContent = 'Mic: on'; showToast('Microphone active · nothing leaves this device'); } catch { $('micButton').textContent = 'Mic: denied'; showToast('Microphone permission denied · manual and demo modes still work'); } }

function syncSetControls() { const label = state.setPlaying ? 'Ⅱ Pause set' : '▶ Play set'; $('playSetButton').textContent = label; $('mobilePlayButton').textContent = label; }
function startSet() { if (state.setPlaying) { state.setPlaying = false; clearTimeout(cueTimer); syncSetControls(); state.currentCue = -1; renderCues(); return showToast('Set paused at current scene'); } state.setPlaying = true; syncSetControls(); let index = state.currentCue >= 0 ? state.currentCue : 0; const play = () => { if (!state.setPlaying) return; const cue = cues[index % cues.length]; state.currentCue = index % cues.length; switchScene(cue.scene, cue.preset, cue); renderCues(); const durationMs = cue.duration * 4 * (60 / state.tempo) * 1000; cueTimer = setTimeout(() => { index += 1; play(); }, durationMs); }; play(); showToast('Rehearsed cue set running · 10 transitions remain bounded'); }
function addCue() { cues.push({ label: `${scene().name} / ${preset()[0]}`, scene: state.sceneIndex, preset: state.presetIndex[state.sceneIndex], duration: 8 }); renderCues(); markDirty(); showToast('Cue added to local set'); }

function sessionData() { return { format: 'phosphor-set-v1', version: 1, activeScene: state.sceneIndex, presetIndex: state.presetIndex, params: state.params, evolution: state.evolution, gestureHistory: state.gestureHistory, phaseEvents: state.phaseEvents, phaseMeasurement: scene().kind === 'phase' ? phaseMeasurement() : null, phaseMeasurementArchive: state.phaseMeasurementArchive, palette, tempo: state.tempo, cues, options: { reducedMotion: state.reducedMotion, brightness: state.brightness, quality: state.quality, workflow: state.workflow } }; }
let saveTimer = null;
function saveLocal() { try { localStorage.setItem('phosphor-set-v1', JSON.stringify(sessionData())); state.dirty = false; $('dirtyState').textContent = 'SAVED'; $('saveReadout').textContent = 'LOCAL ONLY'; } catch { $('saveReadout').textContent = 'DOWNLOAD'; showToast('Storage is full · use Export JSON for a direct file'); } }
function scheduleSave() { clearTimeout(saveTimer); saveTimer = setTimeout(saveLocal, 450); }
function migrateSession(data) { if (!data || data.format !== 'phosphor-set-v1' || data.version !== 1) throw new Error('Unsupported Phosphor set format'); const candidate = structuredClone(data); if (Array.isArray(candidate.presetIndex) && candidate.presetIndex.length === 3) { candidate.presetIndex = [...candidate.presetIndex, ...Array(sceneDefs.length - 3).fill(0)]; const migratedParams = structuredClone(initialParams); for (const id of ['acid', 'tapestry', 'feedback']) if (candidate.params?.[id] && typeof candidate.params[id] === 'object') Object.assign(migratedParams[id], candidate.params[id]); candidate.params = migratedParams; } for (const def of sceneDefs) { if (!candidate.params?.[def.id] || typeof candidate.params[def.id] !== 'object') continue; for (const [key] of def.schema) if (candidate.params[def.id][key] === undefined) candidate.params[def.id][key] = initialParams[def.id][key]; } return candidate; }
